/**
 * Lightweight Self-Contained Offline Mermaid Graph & Diagram Renderer
 * Supports Flowchart (TD/LR/BT/RL), SequenceDiagram, Pie Chart, ClassDiagram, GitGraph
 * Includes Dynamic Node Box Auto-Sizing and Multi-Line Text Wrapping
 */
(function (global) {
    let currentTheme = 'default';

    const THEMES = {
        default: {
            bg: '#ffffff',
            primaryColor: '#0969da',
            nodeBg: '#ddf4ff',
            nodeBorder: '#0969da',
            nodeText: '#24292f',
            lineColor: '#57606a',
            arrowColor: '#57606a',
            textColor: '#24292f',
            subgraphBg: '#f6f8fa',
            subgraphBorder: '#d0d7de'
        },
        dark: {
            bg: '#0d1117',
            primaryColor: '#58a6ff',
            nodeBg: '#1f242c',
            nodeBorder: '#388bfd',
            nodeText: '#c9d1d9',
            lineColor: '#8b949e',
            arrowColor: '#8b949e',
            textColor: '#c9d1d9',
            subgraphBg: '#161b22',
            subgraphBorder: '#30363d'
        }
    };

    function escapeXml(str) {
        return (str || '').replace(/[<>&'"]/g, function (c) {
            switch (c) {
                case '<': return '&lt;';
                case '>': return '&gt;';
                case '&': return '&amp;';
                case '\'': return '&apos;';
                case '"': return '&quot;';
            }
        });
    }

    /**
     * Smart text dimensions estimation & wrapping for CJK and ASCII text
     */
    function measureAndWrapText(text) {
        if (!text) {
            return { lines: [''], width: 120, height: 44, lineHeight: 18 };
        }
        const rawLines = text.split(/\\n|<br\s*\/?>|\n/);
        const wrappedLines = [];
        const maxCharsPerLine = 16; // approx 16 CJK chars or ~30 ASCII chars per line

        rawLines.forEach(function (rawLine) {
            let currentLine = "";
            let currentWeight = 0;
            for (let i = 0; i < rawLine.length; i++) {
                const char = rawLine[i];
                const isCjk = /[\u4e00-\u9fa5\u3040-\u30ff\uff00-\uffef]/.test(char);
                const weight = isCjk ? 1.0 : 0.55;

                if (currentWeight + weight > maxCharsPerLine && currentLine.length > 0) {
                    wrappedLines.push(currentLine);
                    currentLine = char;
                    currentWeight = weight;
                } else {
                    currentLine += char;
                    currentWeight += weight;
                }
            }
            if (currentLine) {
                wrappedLines.push(currentLine);
            }
        });

        if (wrappedLines.length === 0) wrappedLines.push('');

        let maxWidth = 0;
        wrappedLines.forEach(function (line) {
            let width = 0;
            for (let i = 0; i < line.length; i++) {
                const isCjk = /[\u4e00-\u9fa5\u3040-\u30ff\uff00-\uffef]/.test(line[i]);
                width += isCjk ? 14 : 7.5;
            }
            if (width > maxWidth) maxWidth = width;
        });

        const nodeWidth = Math.max(120, Math.round(maxWidth + 32));
        const lineHeight = 18;
        const nodeHeight = Math.max(44, Math.round(20 + wrappedLines.length * lineHeight));

        return {
            lines: wrappedLines,
            width: nodeWidth,
            height: nodeHeight,
            lineHeight: lineHeight
        };
    }

    function renderFlowchart(lines, theme) {
        const firstLine = lines[0].trim();
        const isHorizontal = firstLine.includes('LR') || firstLine.includes('RL');
        const nodes = new Map();
        const edges = [];

        function getOrCreateNode(id, label, shape) {
            id = id.trim();
            if (!nodes.has(id)) {
                const displayLabel = label ? label.trim() : id;
                const dims = measureAndWrapText(displayLabel);
                nodes.set(id, {
                    id: id,
                    label: displayLabel,
                    shape: shape || 'rect',
                    lines: dims.lines,
                    w: dims.width,
                    h: dims.height,
                    lineHeight: dims.lineHeight
                });
            } else if (label) {
                const n = nodes.get(id);
                n.label = label.trim();
                if (shape) n.shape = shape;
                const dims = measureAndWrapText(n.label);
                n.lines = dims.lines;
                n.w = dims.width;
                n.h = dims.height;
                n.lineHeight = dims.lineHeight;
            }
            return nodes.get(id);
        }

        const nodeRegex = /([a-zA-Z0-9_-]+)(?:\[\/?([^\/\]]+)\/?\]|\(([^\)]+)\)|\{([^\}]+)\}|\[\[([^\]]+)\]\]|\[\(([^\)]+)\)\])?/;

        for (let i = 1; i < lines.length; i++) {
            let line = lines[i].trim();
            if (!line || line.startsWith('%%')) continue;

            // Check for links like A -->|text| B or A --- B or A -.-> B or A ==> B
            const linkMatch = line.match(/(.*?)(-->|---|--\s*.*?\s*-->|-\.->|==>|--)(?:\|([^\|]+)\|)?\s*(.*)/);
            if (linkMatch) {
                const leftStr = linkMatch[1].trim();
                const linkType = linkMatch[2].trim();
                const linkText = linkMatch[3] ? linkMatch[3].trim() : '';
                const rightStr = linkMatch[4].trim();

                const leftNodeMatch = leftStr.match(nodeRegex);
                const rightNodeMatch = rightStr.match(nodeRegex);

                if (leftNodeMatch && rightNodeMatch) {
                    const leftId = leftNodeMatch[1];
                    const leftLabel = leftNodeMatch[2] || leftNodeMatch[3] || leftNodeMatch[4] || leftNodeMatch[5] || leftNodeMatch[6];
                    const leftShape = leftNodeMatch[3] ? 'round' : (leftNodeMatch[4] ? 'rhombus' : 'rect');
                    getOrCreateNode(leftId, leftLabel, leftShape);

                    const rightId = rightNodeMatch[1];
                    const rightLabel = rightNodeMatch[2] || rightNodeMatch[3] || rightNodeMatch[4] || rightNodeMatch[5] || rightNodeMatch[6];
                    const rightShape = rightNodeMatch[3] ? 'round' : (rightNodeMatch[4] ? 'rhombus' : 'rect');
                    getOrCreateNode(rightId, rightLabel, rightShape);

                    edges.push({
                        from: leftId,
                        to: rightId,
                        text: linkText,
                        type: linkType
                    });
                }
            } else {
                const singleMatch = line.match(nodeRegex);
                if (singleMatch && singleMatch[1]) {
                    const id = singleMatch[1];
                    const label = singleMatch[2] || singleMatch[3] || singleMatch[4] || singleMatch[5] || singleMatch[6];
                    const shape = singleMatch[3] ? 'round' : (singleMatch[4] ? 'rhombus' : 'rect');
                    getOrCreateNode(id, label, shape);
                }
            }
        }

        // Layout nodes dynamically
        const nodeList = Array.from(nodes.values());
        const gapX = isHorizontal ? 80 : 40;
        const gapY = isHorizontal ? 40 : 50;

        let totalWidth = 0;
        let totalHeight = 0;

        if (isHorizontal) {
            let currentX = 40;
            nodeList.forEach((node, idx) => {
                node.x = currentX;
                node.y = 40 + (idx % 2 === 0 ? 0 : 30);
                currentX += node.w + gapX;
            });
            totalWidth = currentX + 40;
            totalHeight = 180;
        } else {
            let currentY = 40;
            let maxNodeW = 0;
            nodeList.forEach((node, idx) => {
                node.x = 40 + (idx % 2 === 0 ? 0 : 30);
                node.y = currentY;
                if (node.x + node.w > maxNodeW) maxNodeW = node.x + node.w;
                currentY += node.h + gapY;
            });
            totalWidth = maxNodeW + 60;
            totalHeight = currentY + 40;
        }

        let svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${Math.max(totalWidth, 260)} ${Math.max(totalHeight, 120)}" style="background-color: transparent; max-width: 100%; height: auto; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;">`;
        
        // Defs for marker arrows
        svg += `<defs>
            <marker id="arrow-${theme}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto">
                <path d="M 0 0 L 10 5 L 0 10 z" fill="${THEMES[theme].arrowColor}"/>
            </marker>
        </defs>`;

        // Draw Edges
        edges.forEach(edge => {
            const fromNode = nodes.get(edge.from);
            const toNode = nodes.get(edge.to);
            if (fromNode && toNode) {
                const x1 = fromNode.x + fromNode.w / 2;
                const y1 = fromNode.y + fromNode.h;
                const x2 = toNode.x + toNode.w / 2;
                const y2 = toNode.y;

                if (isHorizontal) {
                    const hx1 = fromNode.x + fromNode.w;
                    const hy1 = fromNode.y + fromNode.h / 2;
                    const hx2 = toNode.x;
                    const hy2 = toNode.y + toNode.h / 2;
                    svg += `<path d="M ${hx1} ${hy1} C ${hx1 + 40} ${hy1}, ${hx2 - 40} ${hy2}, ${hx2} ${hy2}" fill="none" stroke="${THEMES[theme].lineColor}" stroke-width="2" marker-end="url(#arrow-${theme})"/>`;
                    if (edge.text) {
                        const midX = (hx1 + hx2) / 2;
                        const midY = (hy1 + hy2) / 2 - 8;
                        svg += `<text x="${midX}" y="${midY}" fill="${THEMES[theme].textColor}" font-size="12" text-anchor="middle">${escapeXml(edge.text)}</text>`;
                    }
                } else {
                    svg += `<path d="M ${x1} ${y1} C ${x1} ${y1 + 25}, ${x2} ${y2 - 25}, ${x2} ${y2}" fill="none" stroke="${THEMES[theme].lineColor}" stroke-width="2" marker-end="url(#arrow-${theme})"/>`;
                    if (edge.text) {
                        const midX = (x1 + x2) / 2 + 10;
                        const midY = (y1 + y2) / 2;
                        svg += `<text x="${midX}" y="${midY}" fill="${THEMES[theme].textColor}" font-size="12" text-anchor="start">${escapeXml(edge.text)}</text>`;
                    }
                }
            }
        });

        // Draw Nodes with Multi-line Centered <tspan>
        nodeList.forEach(node => {
            const rx = node.shape === 'round' ? 16 : (node.shape === 'rhombus' ? 4 : 6);
            svg += `<g class="node">
                <rect x="${node.x}" y="${node.y}" width="${node.w}" height="${node.h}" rx="${rx}" fill="${THEMES[theme].nodeBg}" stroke="${THEMES[theme].nodeBorder}" stroke-width="1.5"/>`;

            const numLines = node.lines.length;
            const startY = node.y + (node.h / 2) - ((numLines - 1) * node.lineHeight / 2) + 4;
            svg += `<text x="${node.x + node.w / 2}" y="${startY}" fill="${THEMES[theme].nodeText}" font-size="13" font-weight="500" text-anchor="middle">`;
            
            node.lines.forEach((lineText, idx) => {
                if (idx === 0) {
                    svg += `<tspan x="${node.x + node.w / 2}">${escapeXml(lineText)}</tspan>`;
                } else {
                    svg += `<tspan x="${node.x + node.w / 2}" dy="${node.lineHeight}">${escapeXml(lineText)}</tspan>`;
                }
            });

            svg += `</text></g>`;
        });

        svg += `</svg>`;
        return svg;
    }

    function renderSequence(lines, theme) {
        const actors = [];
        const messages = [];

        lines.forEach(line => {
            line = line.trim();
            if (!line || line.startsWith('%%') || line.startsWith('sequenceDiagram')) return;

            const actorMatch = line.match(/^actor\s+(.+)|^participant\s+(.+)/);
            if (actorMatch) {
                const name = (actorMatch[1] || actorMatch[2]).trim();
                if (!actors.includes(name)) actors.push(name);
                return;
            }

            const msgMatch = line.match(/^([^-]+)(->>|-->>|->|-->)([^:]+):(.*)/);
            if (msgMatch) {
                const from = msgMatch[1].trim();
                const type = msgMatch[2].trim();
                const to = msgMatch[3].trim();
                const text = msgMatch[4].trim();
                if (!actors.includes(from)) actors.push(from);
                if (!actors.includes(to)) actors.push(to);
                messages.push({ from, to, text, type });
            }
        });

        const actorWidth = 110;
        const actorHeight = 36;
        const gapX = 80;
        const stepY = 50;
        const totalWidth = 60 + actors.length * (actorWidth + gapX);
        const totalHeight = 120 + messages.length * stepY;

        let svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${Math.max(totalWidth, 250)} ${Math.max(totalHeight, 150)}" style="background-color: transparent; max-width: 100%; height: auto; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;">`;
        svg += `<defs>
            <marker id="seq-arrow-${theme}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto">
                <path d="M 0 0 L 10 5 L 0 10 z" fill="${THEMES[theme].arrowColor}"/>
            </marker>
        </defs>`;

        const actorPos = new Map();
        actors.forEach((act, idx) => {
            const x = 30 + idx * (actorWidth + gapX);
            actorPos.set(act, x);

            // Draw Actor Box Top & Bottom
            svg += `<rect x="${x}" y="20" width="${actorWidth}" height="${actorHeight}" rx="4" fill="${THEMES[theme].nodeBg}" stroke="${THEMES[theme].nodeBorder}" stroke-width="1.5"/>
                    <text x="${x + actorWidth / 2}" y="${20 + actorHeight / 2 + 5}" fill="${THEMES[theme].nodeText}" font-size="13" font-weight="500" text-anchor="middle">${escapeXml(act)}</text>`;

            // Lifeline
            svg += `<line x1="${x + actorWidth / 2}" y1="${20 + actorHeight}" x2="${x + actorWidth / 2}" y2="${totalHeight - 30}" stroke="${THEMES[theme].subgraphBorder}" stroke-width="1" stroke-dasharray="4,4"/>`;
        });

        messages.forEach((msg, idx) => {
            const fromX = (actorPos.get(msg.from) || 30) + actorWidth / 2;
            const toX = (actorPos.get(msg.to) || 30) + actorWidth / 2;
            const y = 80 + idx * stepY;
            const isDashed = msg.type === '-->>' || msg.type === '-->';

            svg += `<line x1="${fromX}" y1="${y}" x2="${toX}" y2="${y}" stroke="${THEMES[theme].lineColor}" stroke-width="1.5" ${isDashed ? 'stroke-dasharray="4,4"' : ''} marker-end="url(#seq-arrow-${theme})"/>`;
            svg += `<text x="${(fromX + toX) / 2}" y="${y - 6}" fill="${THEMES[theme].textColor}" font-size="12" text-anchor="middle">${escapeXml(msg.text)}</text>`;
        });

        svg += `</svg>`;
        return svg;
    }

    function renderPie(lines, theme) {
        let title = "Pie Chart";
        const slices = [];
        let total = 0;

        lines.forEach(line => {
            line = line.trim();
            if (!line || line.startsWith('%%')) return;
            if (line.startsWith('title')) {
                title = line.replace('title', '').trim();
                return;
            }
            const match = line.match(/^"([^"]+)"\s*:\s*([\d.]+)|^([^:]+)\s*:\s*([\d.]+)/);
            if (match) {
                const label = (match[1] || match[3]).trim();
                const val = parseFloat(match[2] || match[4]);
                slices.push({ label, val });
                total += val;
            }
        });

        if (total === 0) total = 1;

        const colors = ['#0969da', '#2da44e', '#bf8700', '#cf222e', '#8250df', '#1f883d'];
        let currentAngle = 0;
        const cx = 150, cy = 130, r = 80;

        let svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 280" style="background-color: transparent; max-width: 100%; height: auto; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;">`;
        svg += `<text x="160" y="30" fill="${THEMES[theme].textColor}" font-size="15" font-weight="600" text-anchor="middle">${escapeXml(title)}</text>`;

        slices.forEach((slice, idx) => {
            const angle = (slice.val / total) * 2 * Math.PI;
            const x1 = cx + r * Math.cos(currentAngle);
            const y1 = cy + r * Math.sin(currentAngle);
            const x2 = cx + r * Math.cos(currentAngle + angle);
            const y2 = cy + r * Math.sin(currentAngle + angle);
            const largeArc = angle > Math.PI ? 1 : 0;
            const color = colors[idx % colors.length];

            const path = `M ${cx} ${cy} L ${x1} ${y1} A ${r} ${r} 0 ${largeArc} 1 ${x2} ${y2} Z`;
            svg += `<path d="${path}" fill="${color}" stroke="${THEMES[theme].bg}" stroke-width="1.5"/>`;

            const midAngle = currentAngle + angle / 2;
            const lx = cx + (r + 20) * Math.cos(midAngle);
            const ly = cy + (r + 20) * Math.sin(midAngle);
            const percent = Math.round((slice.val / total) * 100);
            svg += `<text x="${lx}" y="${ly}" fill="${THEMES[theme].textColor}" font-size="11" text-anchor="${lx > cx ? 'start' : 'end'}">${escapeXml(slice.label)} (${percent}%)</text>`;

            currentAngle += angle;
        });

        svg += `</svg>`;
        return svg;
    }

    function render(source, isDarkMode) {
        const theme = isDarkMode ? 'dark' : 'default';
        const lines = (source || '').trim().split('\n').map(l => l.trim()).filter(l => l.length > 0);
        if (lines.length === 0) return '';

        const firstLine = lines[0].toLowerCase();
        try {
            if (firstLine.startsWith('flowchart') || firstLine.startsWith('graph')) {
                return renderFlowchart(lines, theme);
            } else if (firstLine.startsWith('sequencediagram')) {
                return renderSequence(lines, theme);
            } else if (firstLine.startsWith('pie')) {
                return renderPie(lines, theme);
            } else {
                return renderFlowchart(lines, theme);
            }
        } catch (err) {
            console.error('Mermaid render error:', err);
            return '<pre class="language-mermaid"><code>' + escapeXml(source) + '</code></pre>';
        }
    }

    global.mermaid = {
        initialize: function (opts) {
            if (opts && opts.theme) {
                currentTheme = opts.theme === 'dark' ? 'dark' : 'default';
            }
        },
        render: render,
        run: function (options) {
            const isDark = currentTheme === 'dark';
            const elements = document.querySelectorAll('pre.mermaid, div.mermaid, .language-mermaid');
            elements.forEach(function (el) {
                const src = el.textContent || el.innerText;
                const svg = render(src, isDark);
                const container = document.createElement('div');
                container.className = 'mermaid-rendered';
                container.innerHTML = svg;
                if (el.parentNode) {
                    el.parentNode.replaceChild(container, el);
                }
            });
        }
    };
})(window);
